const inputData = $input.first().json;
const tenantId = inputData.tenant_id;
const conversationId = inputData.conversation_id;
const senderType = inputData.sender_type || 'contact';
const messageType = inputData.message_type || 'text';
const content = inputData.content || 'Mensagem de teste automatizada n8n Core';

const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const validSenders = ['contact', 'user', 'agent', 'system'];
const validTypes = ['text', 'image', 'audio', 'video', 'document', 'location', 'system'];

if (!tenantId || !uuidRegex.test(String(tenantId).trim())) {
  return [{
    json: {
      is_valid: false,
      status: "validation_error",
      code: "INVALID_TENANT_ID",
      message: "O parâmetro 'tenant_id' é obrigatório e deve ser um UUID válido",
      timestamp: new Date().toISOString()
    }
  }];
}

if (!conversationId || !uuidRegex.test(String(conversationId).trim())) {
  return [{
    json: {
      is_valid: false,
      status: "validation_error",
      code: "INVALID_CONVERSATION_ID",
      message: "O parâmetro 'conversation_id' é obrigatório e deve ser um UUID válido",
      timestamp: new Date().toISOString()
    }
  }];
}

if (!validSenders.includes(senderType)) {
  return [{
    json: {
      is_valid: false,
      status: "validation_error",
      code: "INVALID_SENDER_TYPE",
      message: `sender_type deve ser um dos seguintes: ${validSenders.join(', ')}`,
      timestamp: new Date().toISOString()
    }
  }];
}

if (!validTypes.includes(messageType)) {
  return [{
    json: {
      is_valid: false,
      status: "validation_error",
      code: "INVALID_MESSAGE_TYPE",
      message: `message_type deve ser um dos seguintes: ${validTypes.join(', ')}`,
      timestamp: new Date().toISOString()
    }
  }];
}

return [{
  json: {
    is_valid: true,
    tenant_id: String(tenantId).trim(),
    conversation_id: String(conversationId).trim(),
    sender_type: senderType,
    message_type: messageType,
    content: String(content),
    metadata: JSON.stringify({ is_test: true, environment: "n8n_test_suite" })
  }
}];

const items = $input.all();
const first = items[0];

if (first.error) {
  return [{
    json: {
      status: "error",
      code: "DB_INSERT_ERROR",
      message: "Erro ao inserir mensagem de teste no PostgreSQL",
      error_details: first.error.message || "Erro desconhecido",
      timestamp: new Date().toISOString()
    }
  }];
}

const msg = first.json;
return [{
  json: {
    status: "success",
    code: "MESSAGE_TEST_CREATED",
    message: "Mensagem de teste gravada com sucesso no PostgreSQL",
    data: {
      message_id: msg.message_id,
      tenant_id: msg.tenant_id,
      conversation_id: msg.conversation_id,
      sender_type: msg.sender_type,
      message_type: msg.message_type,
      content: msg.content,
      metadata: msg.metadata,
      created_at: msg.created_at
    },
    timestamp: new Date().toISOString()
  }
}];
